EXPORT ZZT_VECMIX() BEGIN
LOCAL R,E,O:={}; HComplex:=1; L1:={1,3};
A:=0; E:=0; R:=-99;
IFERR R:=stddev([0+1,3],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],[0+1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([0+1,3],{1,3}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({1,3},[0+1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([-0,3],{-.5,1.5}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],[-.5,1.5]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_VECTOR(D) BEGIN A:=A*10+D; RETURN [1,3]; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

EXPORT ZZT_VECMIX() BEGIN
LOCAL R,E,O:={}; HComplex:=1; L1:={1,3};
A:=0; E:=0; R:=-99;
IFERR R:=stddev([ZZT_TICK(1,1),ZZT_TICK(2,3)],{ZZT_TICK(3,1),ZZT_TICK(4,3)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({ZZT_TICK(1,1),ZZT_TICK(2,3)},[ZZT_TICK(3,1),ZZT_TICK(4,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([ZZT_TICK(1,1),ZZT_TICK(2,3),ZZT_TICK(3,4)],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],[ZZT_TICK(1,1),ZZT_TICK(2,3),ZZT_TICK(3,4)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([ZZT_TICK(1,1),ZZT_TICK(2,3)],{ZZT_TICK(3,1)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({ZZT_TICK(1,1)},[ZZT_TICK(2,1),ZZT_TICK(3,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_VECTOR(D) BEGIN A:=A*10+D; RETURN [1,3]; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

EXPORT ZZT_VECMIX() BEGIN
LOCAL R,E,O:={}; HComplex:=1; L1:={1,3};
A:=0; E:=0; R:=-99;
IFERR R:=stddev(L1,[ZZT_TICK(1,1),ZZT_TICK(2,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([ZZT_TICK(1,1),ZZT_TICK(2,3)],L1); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev(ZZT_VECTOR(1),[ZZT_TICK(2,1),ZZT_TICK(3,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([ZZT_TICK(1,1),ZZT_TICK(2,3)],ZZT_VECTOR(3)); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev(1,[ZZT_TICK(1,1),ZZT_TICK(2,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([ZZT_TICK(1,1),ZZT_TICK(2,3)],1); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
